out = sys.argv[1]
ph = lambda s: sorted(set(re.findall(r"\{\d\}", s)))
for lang, vals in T.items():
    assert len(vals) == len(K), (lang, len(vals))
    for k, en, v in zip(K, T["en"], vals):
        assert ph(en) == ph(v), (lang, k, ph(en), ph(v))
    path = os.path.join(out, lang + ".json")
    d = json.load(open(path, encoding="utf-8")) if os.path.exists(path) else {}
    d.update({"gps_ui_" + k: v for k, v in zip(K, vals)})
    with open(path, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=4)
        f.write("\n")
print(len(T), "languages,", len(K), "keys merged; placeholders checked")
